import argparse

def total(value):
    return sum(int(part) for part in value.split(','))

def main():
    parser = argparse.ArgumentParser(description='Sum comma-separated integers.', epilog='Example: python app.py 1,2,3')
    parser.add_argument('numbers')
    args = parser.parse_args()
    try:
        result = total(args.numbers)
    except ValueError:
        parser.error('numbers must be comma-separated integers')
    print(result)

if __name__ == '__main__':
    main()
